commands.command:
set -euo pipefail; cd interface; npm audit --json >/tmp/matrixhub-publish-audit.json || true; npm audit --omit=dev --json >/tmp/matrixhub-publish-prod-audit.json || true; python3 - <<'PY'
import json,sys
for label,path in [('ALL','/tmp/matrixhub-publish-audit.json'),('PROD','/tmp/matrixhub-publish-prod-audit.json')]:
    d=json.load(open(path)); v=d.get('metadata',{}).get('vulnerabilities',{}); print(label, json.dumps(v, sort_keys=True))
    if v.get('total',0): sys.exit(2)
PY
